// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import { EIP712 } from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import { SignatureChecker } from "@openzeppelin/contracts/utils/cryptography/SignatureChecker.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title TabClob — minimal EIP-712 ERC-20 limit order book
/// @notice Maker signs an off-chain Order (EIP-712). Taker calls `fill` on-chain
///         to atomically swap makerToken/takerToken. Both sides must approve TabClob.
/// @dev    OZ `EIP712` recomputes the domain separator when `block.chainid` differs
///         from the cached chainId, so the contract works correctly on a fork even
///         if the original chainId of the host network changes.
///         `SignatureChecker.isValidSignatureNow` handles both ECDSA EOAs and
///         EIP-1271 contract wallets (smart accounts).
contract TabClob is EIP712, ReentrancyGuard {
    using SafeERC20 for IERC20;

    struct Order {
        address maker;
        address taker; // address(0) = anyone may fill
        address makerToken;
        address takerToken;
        uint128 makerAmount;
        uint128 takerAmount;
        uint64 expiry; // unix seconds
        uint256 salt;
    }

    bytes32 public constant ORDER_TYPEHASH =
        keccak256(
            "Order(address maker,address taker,address makerToken,address takerToken,uint128 makerAmount,uint128 takerAmount,uint64 expiry,uint256 salt)"
        );

    mapping(bytes32 => bool) public filled;
    mapping(bytes32 => bool) public canceled;

    event OrderFilled(
        bytes32 indexed orderHash,
        address indexed maker,
        address indexed taker,
        address makerToken,
        address takerToken,
        uint128 makerAmount,
        uint128 takerAmount
    );
    event OrderCanceled(bytes32 indexed orderHash, address indexed maker);

    error AlreadyFilled();
    error AlreadyCanceled();
    error OrderExpired(uint64 expiry, uint256 currentTime);
    error WrongTaker(address expected, address actual);
    error ZeroAmount();
    error BadSignature();
    error NotMaker(address expected, address actual);

    constructor() EIP712("TabClob", "1") {}

    /// @notice EIP-712 hash of an Order in this contract's domain.
    function hashOrder(Order calldata o) public view returns (bytes32) {
        return
            _hashTypedDataV4(
                keccak256(
                    abi.encode(
                        ORDER_TYPEHASH,
                        o.maker,
                        o.taker,
                        o.makerToken,
                        o.takerToken,
                        o.makerAmount,
                        o.takerAmount,
                        o.expiry,
                        o.salt
                    )
                )
            );
    }

    /// @notice Atomic swap: pulls takerAmount of takerToken from caller to maker,
    ///         then pulls makerAmount of makerToken from maker to caller.
    function fill(Order calldata o, bytes calldata signature) external nonReentrant {
        bytes32 h = hashOrder(o);
        if (filled[h]) revert AlreadyFilled();
        if (canceled[h]) revert AlreadyCanceled();
        if (block.timestamp >= o.expiry) revert OrderExpired(o.expiry, block.timestamp);
        if (o.taker != address(0) && o.taker != msg.sender) revert WrongTaker(o.taker, msg.sender);
        if (o.makerAmount == 0 || o.takerAmount == 0) revert ZeroAmount();
        if (!SignatureChecker.isValidSignatureNow(o.maker, h, signature)) revert BadSignature();

        filled[h] = true;
        IERC20(o.takerToken).safeTransferFrom(msg.sender, o.maker, o.takerAmount);
        IERC20(o.makerToken).safeTransferFrom(o.maker, msg.sender, o.makerAmount);

        emit OrderFilled(h, o.maker, msg.sender, o.makerToken, o.takerToken, o.makerAmount, o.takerAmount);
    }

    /// @notice Maker invalidates an unfilled order. Idempotent: reverts if already filled/canceled.
    function cancel(Order calldata o) external {
        if (msg.sender != o.maker) revert NotMaker(o.maker, msg.sender);
        bytes32 h = hashOrder(o);
        if (filled[h]) revert AlreadyFilled();
        if (canceled[h]) revert AlreadyCanceled();
        canceled[h] = true;
        emit OrderCanceled(h, msg.sender);
    }

    /// @notice Exposed for off-chain signing tools.
    function DOMAIN_SEPARATOR() external view returns (bytes32) {
        return _domainSeparatorV4();
    }
}

contracts/TABcoin.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";

/**
 * @title TABcoin
 * @notice ERC20 token s pevně daným authorizerem:
 *  - jediný možný authorizer je 0x48c5632dCC220Abf56000F93B1C4DEB501c64588
 *  - může mintovat (emitovat) libovolnou částku
 *  - může povolit claim v násobcích (každé povolení = 1× CLAIM_AMOUNT) a případně jednotlivé povolení odebrat
 *  - držitelé mohou pálit (burn) své tokeny
 *
 *  ABI je zachováno: nezměnili jsme signatury funkcí, eventy ani public proměnné.
 */
contract TABcoin is ERC20, ERC20Burnable {
    uint8 private constant _DECIMALS = 18;
    uint256 public constant CLAIM_AMOUNT = 1000 * 10 ** _DECIMALS;

    /// @notice Pevně daný authorizer (neměnný)
    address public constant AUTHORIZER = 0x48c5632dCC220Abf56000F93B1C4DEB501c64588;

    /// @dev Původní public proměnné kvůli ABI (zůstávají):
    /// claimAuthorized: true pokud má adresa >0 povolení
    mapping(address => bool) public claimAuthorized;
    /// claimConsumed: true pokud už někdy claimovala (informativní, neblokuje další claime)
    mapping(address => bool) public claimConsumed;

    /// @dev Interní čítač počtu povolených claimů pro adresu (nezveřejňovat = nemění ABI)
    mapping(address => uint256) private _claimAllowance;

    event ClaimAuthorized(address indexed user);
    event ClaimRevoked(address indexed user);
    event Claimed(address indexed user, uint256 amount);
    event Minted(address indexed to, uint256 amount);

    error NotAuthorizer(address expected, address actual);
    error ZeroAddress();
    error ClaimNotAuthorized();

    constructor() ERC20("TABcoin", "TAB") {}

    modifier onlyAuthorizer() {
        if (msg.sender != AUTHORIZER) revert NotAuthorizer(AUTHORIZER, msg.sender);
        _;
    }

    /// @notice Authorizer přidá JEDNO povolení claimu dané adrese (může volat opakovaně)
    function authorizeClaim(address user) external onlyAuthorizer {
        if (user == address(0)) revert ZeroAddress();
        unchecked {
            _claimAllowance[user] += 1;
        }
        // držíme synchronizaci s původním veřejným ukazatelem
        claimAuthorized[user] = (_claimAllowance[user] > 0);
        emit ClaimAuthorized(user);
    }

    /// @notice Authorizer odebere JEDNO dříve přidané povolení claimu (pokud nějaké zbývá)
    function revokeClaim(address user) external onlyAuthorizer {
        if (_claimAllowance[user] > 0) {
            _claimAllowance[user] -= 1;
        }
        claimAuthorized[user] = (_claimAllowance[user] > 0);
        emit ClaimRevoked(user);
    }

    /// @notice Uživatel provede claim (pokud má k dispozici alespoň jedno povolení)
    function claim() external {
        uint256 allowanceLeft = _claimAllowance[msg.sender];
        if (allowanceLeft == 0) revert ClaimNotAuthorized();

        // odebereme jedno „povolení“ a mintneme CLAIM_AMOUNT
        _claimAllowance[msg.sender] = allowanceLeft - 1;
        claimAuthorized[msg.sender] = (_claimAllowance[msg.sender] > 0);

        // historická informace – někdy claimnul
        if (!claimConsumed[msg.sender]) {
            claimConsumed[msg.sender] = true;
        }

        _mint(msg.sender, CLAIM_AMOUNT);
        emit Claimed(msg.sender, CLAIM_AMOUNT);
    }

    /// @notice Authorizer může mintovat libovolné množství tokenů
    function mint(address to, uint256 amount) external onlyAuthorizer {
        _mint(to, amount);
        emit Minted(to, amount);
    }

    function decimals() public pure override returns (uint8) {
        return _DECIMALS;
    }
}
